/* @lc app=leetcode id=3607 lang=kotlin */ class Solution { fun find(p: IntArray, x: Int): Int = generateSequence(x) { if (p[it] == it) null else p[it] }.toList().let { path -> path.last().also { r -> path.forEach { p[it] = r } } } fun processQueries(c: Int, connections: Array<IntArray>, queries: Array<IntArray>): IntArray = IntArray(c + 1) { it }.let { p -> connections.forEach { (a, b) -> p[find(p, a)] = find(p, b) }.let { BooleanArray(c + 1).let { off -> (1..c).groupBy { find(p, it) }.mapValues { java.util.TreeSet(it.value) }.let { sets -> queries.mapNotNull { (t, x) -> if (t == 1) (if (!off[x]) x else sets[find(p, x)]!!.let { s -> if (s.isEmpty()) -1 else s.first() }) else off.set(x, true).let { sets[find(p, x)]!!.remove(x) }.let { null } }.toIntArray() } } } } }